UPDATE `lounges` SET `description_en` = 'Berlin\'s La Casa del Habano, in the Hotel Savoy on Fasanenstrasse.', `description_es` = 'La Casa del Habano de Berlín, en el Hotel Savoy de la Fasanenstrasse.', `description_de` = 'Die La Casa del Habano in Berlin, im Hotel Savoy in der Fasanenstraße.', `description_zh` = '柏林的 La Casa del Habano，位于 Fasanenstrasse 的萨伏依酒店内。', `description_ar` = '«لا كاسا ديل هابانو» في برلين، بفندق سافوي في شارع فازانن.' WHERE `id` = '40';
UPDATE `lounges` SET `description_en` = 'Opened in 2025, Germany\'s 16th La Casa del Habano.', `description_es` = 'Inaugurada en 2025, la 16.ª La Casa del Habano de Alemania.', `description_de` = '2025 eröffnet, die 16. La Casa del Habano Deutschlands.', `description_zh` = '2025 年开业，德国第 16 家 La Casa del Habano。', `description_ar` = 'افتُتح عام 2025، وهو سادس عشر «لا كاسا ديل هابانو» في ألمانيا.' WHERE `id` = '41';
